struct Guarded {MetalBuffer base,view;};
struct ScopeFinalizer {std::function<void()>fn;~ScopeFinalizer(){fn();}};
Guarded allocate(MetalBackend&b,uint64_t bytes,std::vector<Guarded>&all){auto base=b.allocateBuffer(mp::guarded(bytes),BufferStorage::Shared,"bounded-main-RHS");std::memset(base.contents(),0xa5,base.sizeBytes());auto view=b.view(base,mp::guard,bytes);std::memset(view.contents(),0,bytes);Guarded a{base,view};all.push_back(a);return a;}
void guards(const std::vector<Guarded>&all){for(const auto&a:all){auto*p=static_cast<const uint8_t*>(a.base.contents());for(uint64_t i=0;i<mp::guard;++i)require(p[i]==0xa5,"leading guard");for(uint64_t i=mp::guard+a.view.sizeBytes();i<a.base.sizeBytes();++i)require(p[i]==0xa5,"trailing/padding guard");}}
void disjoint(MetalBuffer a,MetalBuffer b){auto x=reinterpret_cast<uintptr_t>(a.contents()),y=reinterpret_cast<uintptr_t>(b.contents());require(a&&b&&x&&y,"addressable Shared view");require(x<=y?y-x>=a.sizeBytes():x-y>=b.sizeBytes(),"range overlap");}
bool equal(MetalBuffer a,MetalBuffer b,Progress&p,const std::string&name){require(a.sizeBytes()==b.sizeBytes(),name+" extent");p.check=name;auto*x=static_cast<const uint8_t*>(a.contents()),*y=static_cast<const uint8_t*>(b.contents());for(uint64_t i=0;i<a.sizeBytes();++i)if(x[i]!=y[i]){if(p.first==UINT64_MAX){p.first=i;p.firstPlane=name;}return false;}p.compared+=a.sizeBytes();++p.checks;return true;}
std::string hash(MetalBuffer b){return one::detail::hash(b.contents(),b.sizeBytes());}
void finite(MetalBuffer b,bool half,uint64_t active){require(active*(half?2:4)<=b.sizeBytes(),"finite active extent");for(uint64_t i=0;i<active;++i)require(std::isfinite(half?number(static_cast<const uint16_t*>(b.contents())[i]):static_cast<const float*>(b.contents())[i]),"nonfinite real output");}
uint32_t diag(MetalBuffer b){return *static_cast<const uint32_t*>(b.contents());}
void reset(MetalBuffer b){*static_cast<uint32_t*>(b.contents())=0x80000000u;}
std::vector<uint8_t> copied(MetalBuffer b){const auto*p=static_cast<const uint8_t*>(b.contents());return{p,p+b.sizeBytes()};}
